        <select id="npPackageType"><option value="Standard">Standard</option><option value="Family">Family</option><option value="Luxury">Luxury</option><option value="Group">Group</option></select>
        <input type="date" id="npDeparture">
        <input type="date" id="npReturn">
        <input type="number" id="npDuration" placeholder="عدد الأيام">
        <input type="number" id="npPrice" placeholder="السعر (BHD)">
        <input type="number" id="npSeats" placeholder="عدد المقاعد">
        <select id="npStatus"><option value="Draft">Draft</option><option value="Active">Active</option></select>
        <label style="display:flex;align-items:center;gap:6px;"><input type="checkbox" id="npVisa"> تشمل التأشيرة</label>
        <label style="display:flex;align-items:center;gap:6px;"><input type="checkbox" id="npVisible" checked> ظاهرة للعملاء</label>
      </div>
      <textarea id="npDescription" rows="3" placeholder="الوصف التفصيلي" style="width:100%;margin-top:10px;padding:10px;border:1px solid var(--line);border-radius:8px;font-family:inherit;"></textarea>
      <label style="display:block;margin-top:14px;font-weight:700;color:var(--blue);">
        🎨 توليد تصميم إعلان بالذكاء الاصطناعي (اختياري)
      </label>
      <input type="text" id="npDesignStyle" placeholder="أسلوب التصميم (اختياري، مثلاً: فخم وهادئ)" style="width:100%;margin-top:8px;">
      <div id="designPreviewWrap" style="display:none;margin-top:14px;">
        <img id="designPreviewImg" style="width:100%;border-radius:12px;border:1px solid var(--line);">
        <div style="font-size:0.8rem;color:#6b7f7c;text-align:center;margin-top:6px;">معاينة أولية — راجعها قبل الاستخدام بالإعلانات الفعلية</div>
      </div>
      <div id="npMsg" style="font-size:0.85rem;text-align:center;margin-top:10px;min-height:18px;"></div>
      <div style="display:flex;gap:10px;margin-top:16px;flex-wrap:wrap;">
        <button class="refresh-btn" id="npGenDesignBtn" style="flex:1;min-width:120px;">🎨 ولّد تصميم</button>
        <button class="save-btn" id="npSubmit" style="flex:1;min-width:120px;padding:12px;font-size:0.95rem;" data-mode="create">✓ حفظ الباقة</button>
        <button class="refresh-btn" id="npCloneBtn" style="flex:1;min-width:120px;display:none;">⧉ استنساخ كباقة جديدة</button>
        <button class="refresh-btn" id="npCancel" style="flex:1;min-width:120px;">إلغاء</button>
      </div>
    </div>
  </div>
</div>
<div class="toast" id="toast"></div>
<script>
(function(){
  var API = "https://n8n-production-47b1.up.railway.app/webhook/admin-api";
  var passcode = null;
  function showToast(msg, isError){
    var t = document.getElementById("toast");
    t.textContent = msg;
    t.style.background = isError ? "#C0392B" : "#0B2E52";
    t.classList.add("show");
    setTimeout(function(){ t.classList.remove("show"); }, 2400);
  }
  function callApi(payload){
    return fetch(API, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(Object.assign({ passcode: passcode }, payload)) }).then(function(res){ return res.json(); });
  }
  function tryLogin(pc){
    passcode = pc;
    callApi({ action: "listBookings" }).then(function(data){
      if (data && data.success) {
        try { localStorage.setItem("almutawa_admin_pc", pc); } catch(e){}
        document.getElementById("gate").style.display = "none";
        document.getElementById("app").style.display = "block";
        renderBookings(data.bookings);
        loadPackages();
      } else {
        document.getElementById("gateError").textContent = "كلمة المرور غير صحيحة";
      }
    }).catch(function(){
      document.getElementById("gateError").textContent = "صار خطأ بالاتصال، حاول مرة ثانية";
    });
  }
  document.getElementById("loginBtn").addEventListener("click", function(){
    var pc = document.getElementById("passcodeInput").value.trim();
    if (!pc) return;
    tryLogin(pc);
  });
  document.getElementById("passcodeInput").addEventListener("keydown", function(e){
    if (e.key === "Enter") document.getElementById("loginBtn").click();
  });
  document.getElementById("logoutBtn").addEventListener("click", function(){
    try { localStorage.removeItem("almutawa_admin_pc"); } catch(e){}
    location.reload();
  });
  var savedPc = null;
  try { savedPc = localStorage.getItem("almutawa_admin_pc"); } catch(e){}
  if (savedPc) tryLogin(savedPc);
  document.querySelectorAll(".tabs button").forEach(function(btn){
    btn.addEventListener("click", function(){
      document.querySelectorAll(".tabs button").forEach(function(b){ b.classList.remove("active"); });
      btn.classList.add("active");
      var tab = btn.getAttribute("data-tab");
      document.getElementById("bookingsPanel").style.display = tab === "bookings" ? "block" : "none";
      document.getElementById("packagesPanel").style.display = tab === "packages" ? "block" : "none";
    });
  });
  var BOOKING_STATUSES = ["Pending", "Confirmed", "Cancelled"];
  var PAYMENT_STATUSES = ["Unpaid", "Paid", "Partial"];
  function loadBookings(){
    document.getElementById("bookingsBody").innerHTML = '<tr><td colspan="8" class="loading-msg">جاري التحميل...</td></tr>';
    callApi({ action: "listBookings" }).then(function(data){ if (data && data.success) renderBookings(data.bookings); });
  }
  function renderBookings(rows){
    var tbody = document.getElementById("bookingsBody");
    tbody.innerHTML = "";
    if (!rows || !rows.length) { tbody.innerHTML = '<tr><td colspan="8" class="empty-msg">ما فيه حجوزات حالياً</td></tr>'; return; }
    rows.forEach(function(r){
      var tr = document.createElement("tr");
      tr.innerHTML = '<td>' + escapeHtml(r.customerName) + '</td>' + '<td>' + escapeHtml(r.customerPhone) + '</td>' + '<td>' + escapeHtml(r.packageTitle) + '</td>' + '<td><input type="number" class="f-travelers" value="' + (r.travelers || 0) + '"></td>' + '<td>' + selectHtml("f-bstatus", BOOKING_STATUSES, r.bookingStatus) + '</td>' + '<td>' + selectHtml("f-pstatus", PAYMENT_STATUSES, r.paymentStatus) + '</td>' + '<td><textarea class="f-notes" rows="1">' + escapeHtml(r.notes) + '</textarea></td>' + '<td><button class="save-btn">حفظ</button></td>';
      tr.querySelector(".save-btn").addEventListener("click", function(){
        var btn = tr.querySelector(".save-btn");
        btn.classList.add("saving"); btn.textContent = "...";
        callApi({ action: "updateBooking", bookingId: r.id, travelers: parseInt(tr.querySelector(".f-travelers").value, 10) || 0, bookingStatus: tr.querySelector(".f-bstatus").value, paymentStatus: tr.querySelector(".f-pstatus").value, notes: tr.querySelector(".f-notes").value }).then(function(data){
          btn.classList.remove("saving"); btn.textContent = "حفظ";
          showToast(data && data.success ? "تم الحفظ ✓" : "فشل الحفظ", !(data && data.success));
        }).catch(function(){ btn.classList.remove("saving"); btn.textContent = "حفظ"; showToast("فشل الحفظ", true); });
      });
      tbody.appendChild(tr);
    });
  }
  var PKG_STATUSES = ["Draft", "Active", "Expired", "Sold Out", "Cancelled"];
  function loadPackages(){
    document.getElementById("packagesBody").innerHTML = '<tr><td colspan="8" class="loading-msg">جاري التحميل...</td></tr>';
    callApi({ action: "listPackages" }).then(function(data){ if (data && data.success) renderPackages(data.packages); });
  }
  function renderPackages(rows){
    var tbody = document.getElementById("packagesBody");
    tbody.innerHTML = "";
    if (!rows || !rows.length) { tbody.innerHTML = '<tr><td colspan="8" class="empty-msg">ما فيه باقات</td></tr>'; return; }
    rows.forEach(function(r){
      var tr = document.createElement("tr");
      tr.innerHTML = '<td>' + escapeHtml(r.title) + '</td>' + '<td>' + escapeHtml(r.destination) + '</td>' + '<td>' + (r.price || 0) + ' BHD</td>' + '<td>' + (r.seats || 0) + '</td>' + '<td>' + escapeHtml(r.status) + '</td>' + '<td class="checkbox-cell">' + (r.isVisible ? "\u2713" : "\u2014") + '</td>' + '<td>' + escapeHtml(r.departureDate) + '</td>' + '<td><button class="save-btn view-btn">\ud83d\udc41 عرض</button></td>';
      tr.querySelector(".view-btn").addEventListener("click", function(){ openPackageModal(r); });
      tbody.appendChild(tr);
    });
  }
  var pkgFormModal = document.getElementById("pkgFormModal");
  var editingPackageId = null;
  function resetForm(){
    ["npTitle","npDestination","npDuration","npPrice","npSeats","npDesignStyle"].forEach(function(id){ document.getElementById(id).value = ""; });
    document.getElementById("npDescription").value = "";
    document.getElementById("npDeparture").value = ""; document.getElementById("npReturn").value = "";
    document.getElementById("npVisa").checked = false; document.getElementById("npVisible").checked = true;
    document.getElementById("npTransport").value = "Flight"; document.getElementById("npPackageType").value = "Standard"; document.getElementById("npStatus").value = "Draft";
    document.getElementById("designPreviewWrap").style.display = "none";
    document.getElementById("npMsg").textContent = "";
  }
  document.getElementById("addPackageBtn").addEventListener("click", function(){
    editingPackageId = null;
    resetForm();
    document.getElementById("pkgFormTitle").textContent = "إضافة باقة جديدة";
    document.getElementById("npSubmit").textContent = "✓ حفظ الباقة";
    document.getElementById("npCloneBtn").style.display = "none";
    pkgFormModal.classList.add("open");
  });
  function openPackageModal(r){
    editingPackageId = r.id;
    resetForm();
    document.getElementById("npTitle").value = r.title || "";
    document.getElementById("npDestination").value = r.destination || "";
    document.getElementById("npTransport").value = r.transportType || "Flight";
    document.getElementById("npPackageType").value = r.packageType || "Standard";
    document.getElementById("npDeparture").value = r.departureDate || "";
    document.getElementById("npReturn").value = r.returnDate || "";
    document.getElementById("npDuration").value = r.durationDays || "";
    document.getElementById("npPrice").value = r.price || "";
    document.getElementById("npSeats").value = r.seats || "";
    document.getElementById("npStatus").value = r.status || "Draft";
    document.getElementById("npVisa").checked = !!r.includesVisa;
    document.getElementById("npVisible").checked = !!r.isVisible;
    document.getElementById("npDescription").value = r.description || "";
    document.getElementById("pkgFormTitle").textContent = "عرض / تعديل الباقة";
    document.getElementById("npSubmit").textContent = "✓ حفظ التعديلات";
    document.getElementById("npCloneBtn").style.display = "block";
    pkgFormModal.classList.add("open");
  }
  document.getElementById("npCancel").addEventListener("click", function(){ pkgFormModal.classList.remove("open"); });
  function collectFormPayload(){
    return {
      title: document.getElementById("npTitle").value.trim(),
      destination: document.getElementById("npDestination").value.trim(),
      transportType: document.getElementById("npTransport").value,
      packageType: document.getElementById("npPackageType").value,
      departureDate: document.getElementById("npDeparture").value,
      returnDate: document.getElementById("npReturn").value,
      durationDays: parseInt(document.getElementById("npDuration").value, 10) || 0,
      price: parseFloat(document.getElementById("npPrice").value) || 0,
      seatsAvailable: parseInt(document.getElementById("npSeats").value, 10) || 0,
      seats: parseInt(document.getElementById("npSeats").value, 10) || 0,
      status: document.getElementById("npStatus").value,
      includesVisa: document.getElementById("npVisa").checked,
      isVisible: document.getElementById("npVisible").checked,
      description: document.getElementById("npDescription").value.trim()
    };
  }
  document.getElementById("npGenDesignBtn").addEventListener("click", function(){
    var destination = document.getElementById("npDestination").value.trim();
    var msgEl = document.getElementById("npMsg");
    if (!destination) { msgEl.style.color = "#C0392B"; msgEl.textContent = "اكتب الوجهة أول عشان نولّد لك تصميم مناسب"; return; }
    var genBtn = document.getElementById("npGenDesignBtn");
    genBtn.disabled = true; genBtn.textContent = "جاري التوليد...";
    msgEl.style.color = "#6b7f7c"; msgEl.textContent = "جاري توليد التصميم بالذكاء الاصطناعي (قد يأخذ نص دقيقة)...";
    var payload = Object.assign({ action: "generateDesign", designStyle: document.getElementById("npDesignStyle").value.trim() }, collectFormPayload());
    callApi(payload).then(function(designData){
      genBtn.disabled = false; genBtn.textContent = "🎨 ولّد تصميم";
      if (designData && designData.success) {
        document.getElementById("designPreviewImg").src = designData.imageDataUrl;
        document.getElementById("designPreviewWrap").style.display = "block";
        msgEl.style.color = "#1DA851"; msgEl.textContent = "تم توليد معاينة التصميم ✓ (راجعها بالأسفل)";
      } else {
        msgEl.style.color = "#C0392B"; msgEl.textContent = "فشل توليد التصميم، جرب مرة ثانية";
      }
