    if (!title || !destination) { msgEl.style.color = "#C0392B"; msgEl.textContent = "الرجاء تعبئة العنوان والوجهة على الأقل"; return; }
    var btn = document.getElementById("npSubmit");
    btn.disabled = true; msgEl.style.color = "#6b7f7c"; msgEl.textContent = "جاري الحفظ...";
    var payload = Object.assign(
      { action: editingPackageId ? "updatePackage" : "createPackage" },
      editingPackageId ? { packageId: editingPackageId } : {},
      collectFormPayload()
    );
    callApi(payload).then(function(data){
      btn.disabled = false;
      if (!data || !data.success) { msgEl.style.color = "#C0392B"; msgEl.textContent = "فشل الحفظ"; return; }
      msgEl.style.color = "#1DA851"; msgEl.textContent = "✓ تم الحفظ بنجاح";
      loadPackages();
      setTimeout(function(){ pkgFormModal.classList.remove("open"); }, 900);
    }).catch(function(){ btn.disabled = false; msgEl.style.color = "#C0392B"; msgEl.textContent = "فشل الحفظ"; });
  });
  document.getElementById("npCloneBtn").addEventListener("click", function(){
    var msgEl = document.getElementById("npMsg");
    var title = document.getElementById("npTitle").value.trim();
    var destination = document.getElementById("npDestination").value.trim();
    if (!title || !destination) { msgEl.style.color = "#C0392B"; msgEl.textContent = "الرجاء تعبئة العنوان والوجهة على الأقل"; return; }
    var btn = document.getElementById("npCloneBtn");
    btn.disabled = true; msgEl.style.color = "#6b7f7c"; msgEl.textContent = "جاري الاستنساخ...";
    var payload = Object.assign({ action: "createPackage" }, collectFormPayload());
    payload.status = "Draft";
    callApi(payload).then(function(data){
      btn.disabled = false;
