  });
  function selectHtml(cls, options, current){
    var html = '<select class="' + cls + '">';
    options.forEach(function(o){ html += '<option value="' + o + '"' + (o === current ? " selected" : "") + '>' + o + '</option>'; });
    html += '</select>';
    return html;
  }
  function escapeHtml(s){
    return String(s == null ? "" : s).replace(/[&<>"']/g, function(c){ return { "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[c]; });
  }
  document.getElementById("refreshBookings").addEventListener("click", loadBookings);
  document.getElementById("refreshPackages").addEventListener("click", loadPackages);
})();
</script>
</body>
</html>`;
return [{ json: { html: html } }];

