<script>
document.getElementById('f').addEventListener('submit', function(e){
  e.preventDefault();
  var fileInput = document.getElementById('file');
  var msg = document.getElementById('msg');
  if (!fileInput.files.length) return;
  msg.textContent = 'جاري الرفع...'; msg.style.color = '#666';
  var fd = new FormData();
  fd.append('file', fileInput.files[0]);
  fetch('https://n8n-production-47b1.up.railway.app/webhook/upload-logo-submit', { method: 'POST', body: fd })
    .then(function(r){ return r.json(); })
    .then(function(data){
      if (data && data.success) {
        msg.style.color = '#1DA851';
        msg.innerHTML = 'تم الرفع ✓<br><br><a href="' + data.url + '" target="_blank" style="word-break:break-all;">' + data.url + '</a>';
      } else {
        msg.style.color = '#C0392B'; msg.textContent = 'فشل الرفع، جرب مرة ثانية';
      }
    }).catch(function(){ msg.style.color = '#C0392B'; msg.textContent = 'فشل الرفع، جرب مرة ثانية'; });
});
</script></body></html>`;
